BEGIN;
create temp table assertion_count(n int);insert into assertion_count values(0);
create function pg_temp.check_it(v boolean,label text)returns void language plpgsql as $$begin if v is distinct from true then raise exception 'Assertion failed: %',label;end if;update assertion_count set n=n+1;end$$;
create temp table st(k text primary key,v jsonb);
insert into public.properties(id,org_id,name)values('ee330000-0000-4000-8000-000000000001','22222222-2222-2222-2222-222222222222','Private file SQL fixture'),('ee330000-0000-4000-8000-000000000002','22222222-2222-2222-2222-222222222222','Other private file SQL fixture');
create function pg_temp.original(p_file uuid,p_material uuid default null)returns jsonb language sql as $$select public.begin_knowledge_file(p_file,'ee330000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111',jsonb_build_object('title','Exact private source','fileName','source.pdf','mimeType','application/pdf','size',100,'byteHash',repeat('a',64),'materialId',p_material,'reason','Retain exact synthetic original'))$$;
create function pg_temp.command(p_file uuid,p_op text,p_more jsonb default '{}')returns jsonb language sql as $$select jsonb_build_object('fileId',p_file,'operation',p_op,'expectedRevision',(select revision from public.knowledge_files where id=p_file),'reason','Review exact synthetic file decision')||p_more$$;
create function pg_temp.decide(p_id uuid,p_input jsonb)returns jsonb language sql as $$select public.decide_knowledge_file(p_id,'ee330000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111',p_input)$$;
create function pg_temp.finish_file(p_id uuid)returns jsonb language sql as $$select public.finish_knowledge_file_storage(p_id,'11111111-1111-1111-1111-111111111111',repeat('a',64),100)$$;
select pg_temp.check_it(pg_temp.original('ee330000-0000-4000-8000-000000000010')->>'state'='saved','original intent saved before bytes');
select pg_temp.check_it(pg_temp.original('ee330000-0000-4000-8000-000000000010')->>'state'='replayed','exact original request replay');
select pg_temp.check_it((select count(*)from public.knowledge_files where property_id='ee330000-0000-4000-8000-000000000001')=1,'replay creates no duplicate file');
select pg_temp.check_it(public.begin_knowledge_file('ee330000-0000-4000-8000-000000000010','ee330000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111',(select input||'{"title":"Different"}'from public.knowledge_files where id='ee330000-0000-4000-8000-000000000010'))->>'state'='request_conflict','changed original identity rejected');
select pg_temp.check_it(public.read_knowledge_files('ee330000-0000-4000-8000-000000000002','11111111-1111-1111-1111-111111111111','{"kind":"file","fileId":"ee330000-0000-4000-8000-000000000010"}')->>'state'='not_found','file cannot cross property');
select pg_temp.check_it(public.read_knowledge_files('ee330000-0000-4000-8000-000000000001',gen_random_uuid(),'{}')->>'state'='forbidden','unknown actor denied');
select pg_temp.check_it(pg_temp.decide(gen_random_uuid(),pg_temp.command('ee330000-0000-4000-8000-000000000010','extract'))->>'state'='closed_request','unverified original cannot extract');
select pg_temp.check_it(public.finish_knowledge_file_storage('ee330000-0000-4000-8000-000000000010','11111111-1111-1111-1111-111111111111',repeat('b',64),100)->>'state'='bytes_changed','mismatched original hash held');
select pg_temp.check_it(pg_temp.finish_file('ee330000-0000-4000-8000-000000000010')->>'state'='ready','verified synthetic byte receipt finalizes');
select pg_temp.check_it(pg_temp.finish_file('ee330000-0000-4000-8000-000000000010')->>'state'='ready','storage receipt idempotent');
insert into st values('startInput',pg_temp.command('ee330000-0000-4000-8000-000000000010','extract'));
select pg_temp.check_it(pg_temp.decide('ee330000-0000-4000-8000-000000000020',(select v from st where k='startInput'))->>'state'='saved','explicit extraction retained');
select pg_temp.check_it(pg_temp.decide('ee330000-0000-4000-8000-000000000020',(select v from st where k='startInput'))->>'state'='replayed','extraction start replays');
insert into st values('claim',public.claim_knowledge_file_extraction('ee330000-0000-4000-8000-000000000020'));
select pg_temp.check_it(v->>'state'='invoke_once','one local extraction claim')from st where k='claim';
select pg_temp.check_it(public.claim_knowledge_file_extraction('ee330000-0000-4000-8000-000000000020')->>'state'='running','repeated claim never invokes again');
select pg_temp.check_it(public.record_knowledge_file_extraction('ee330000-0000-4000-8000-000000000020',(select(v->>'claimToken')::uuid from st where k='claim'),'{"complete":true,"totalPages":"invalid","pages":[],"text":"incomplete"}')->>'state'='held','malformed receipt retained as held');
select pg_temp.check_it((select receipt is not null from public.knowledge_file_extractions where id='ee330000-0000-4000-8000-000000000020'),'invalid raw receipt retained');
select pg_temp.check_it(pg_temp.decide('ee330000-0000-4000-8000-000000000021',pg_temp.command('ee330000-0000-4000-8000-000000000010','extract'))->>'state'='saved','new explicit local extraction after held');
insert into st values('claim2',public.claim_knowledge_file_extraction('ee330000-0000-4000-8000-000000000021'));
insert into st values('receipt',jsonb_build_object('recipe','unpdf-1.4.0-pages-v1','fileHash',repeat('a',64),'complete',true,'totalPages',2,'pages',jsonb_build_array(E'Original exact policy.\r\n','Second page 🏡'),'text',E'Original exact policy.\r\n\n\nSecond page 🏡','blankPages','[]'::jsonb,'limitations',jsonb_build_array('Synthetic local page order')));
select pg_temp.check_it(public.record_knowledge_file_extraction('ee330000-0000-4000-8000-000000000021',(select(v->>'claimToken')::uuid from st where k='claim2'),(select v from st where k='receipt'))->>'state'='ready','complete exact ordered pages ready for review');
select pg_temp.check_it(public.record_knowledge_file_extraction('ee330000-0000-4000-8000-000000000021',(select(v->>'claimToken')::uuid from st where k='claim2'),(select v from st where k='receipt'))->>'state'='ready','lost receipt response idempotent');
select pg_temp.check_it(public.record_knowledge_file_extraction('ee330000-0000-4000-8000-000000000021',(select(v->>'claimToken')::uuid from st where k='claim2'),(select v||'{"text":"Changed"}'from st where k='receipt'))->>'state'='receipt_changed','original receipt cannot change');
select pg_temp.check_it(not exists(select 1 from public.documents where property_id='ee330000-0000-4000-8000-000000000001'),'extraction never publishes documents');
insert into st select'accept',pg_temp.command('ee330000-0000-4000-8000-000000000010','accept',jsonb_build_object('extractionId',id,'expectedExtractionRevision',revision,'receiptHash',receipt_hash,'content','Deliberate reviewed correction.','materialId',null,'previousVersionId',null,'confirmed',true))from public.knowledge_file_extractions where id='ee330000-0000-4000-8000-000000000021';
select pg_temp.check_it(pg_temp.decide(gen_random_uuid(),(select v||jsonb_build_object('receiptHash',repeat('b',64))from st where k='accept'))->>'state'='extraction_changed','review binds exact raw receipt');

create function pg_temp.fail_file_review()returns trigger language plpgsql as $$begin if new.action='knowledge.file.reviewed'then raise exception 'Synthetic review history failure';end if;return new;end$$;
create trigger fixture_file_review_failure before insert on public.shared_action_events for each row execute function pg_temp.fail_file_review();
do $$begin begin perform pg_temp.decide('ee330000-0000-4000-8000-000000000039',(select v from st where k='accept'));raise exception 'Expected review rollback'using errcode='P0002';exception when sqlstate'P0001'then if sqlerrm<>'Synthetic review history failure'then raise;end if;perform pg_temp.check_it(true,'review failure reaches atomic history boundary');end;end$$;
drop trigger fixture_file_review_failure on public.shared_action_events;
select pg_temp.check_it(not exists(select 1 from public.knowledge_material_versions where property_id='ee330000-0000-4000-8000-000000000001')and not exists(select 1 from public.knowledge_file_links where property_id='ee330000-0000-4000-8000-000000000001'),'review failure rolls back material and file lineage together');
insert into st values('accepted',pg_temp.decide('ee330000-0000-4000-8000-000000000030',(select v from st where k='accept')));
select pg_temp.check_it(v->>'state'='saved'and v->'published'='false','accept saves private text only')from st where k='accepted';
select pg_temp.check_it(pg_temp.decide('ee330000-0000-4000-8000-000000000030',(select v from st where k='accept'))->>'state'='replayed','accept lost reply replays exact source version');
select pg_temp.check_it((select count(*)from public.knowledge_material_versions where property_id='ee330000-0000-4000-8000-000000000001')=1,'one source version after repeated accept');
select pg_temp.check_it((select content from public.knowledge_material_versions where property_id='ee330000-0000-4000-8000-000000000001')='Deliberate reviewed correction.','exact operator correction retained');
select pg_temp.check_it(public.knowledge_version_file_origin((select(v->>'versionId')::uuid from st where k='accepted'))->>'fileId'='ee330000-0000-4000-8000-000000000010','source linked to immutable original');
select pg_temp.check_it(public.read_knowledge_materials('ee330000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111',jsonb_build_object('kind','version','materialId',(select v->>'materialId'from st where k='accepted')))->'fileOrigin'->>'fileName'='source.pdf','material details retain original ancestry');
select pg_temp.check_it((select active_version_id is null from public.knowledge_materials where property_id='ee330000-0000-4000-8000-000000000001'),'accept never changes publication');
insert into st values('correction',public.save_knowledge_material('ee330000-0000-4000-8000-000000000031','ee330000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111',jsonb_build_object('materialId',(select v->>'materialId'from st where k='accepted'),'previousVersionId',(select v->>'versionId'from st where k='accepted'),'title','Later source correction','content','New corrected text','reason','Review later correction')));
select pg_temp.check_it(public.knowledge_version_file_origin('ee330000-0000-4000-8000-000000000031')->'inherited'='true','later corrections retain original ancestry');
insert into st values('downloadInput',pg_temp.command('ee330000-0000-4000-8000-000000000010','download'));
select pg_temp.check_it(pg_temp.decide('ee330000-0000-4000-8000-000000000040',(select v from st where k='downloadInput'))->'prepared'='true','original download preparation recorded');
select pg_temp.check_it(public.read_knowledge_files('ee330000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111','{"kind":"decision","decisionId":"ee330000-0000-4000-8000-000000000040"}')->>'fileId'='ee330000-0000-4000-8000-000000000010','download preparation addressable');
select pg_temp.check_it(public.cancel_unused_knowledge_decision('ee330000-0000-4000-8000-000000000010','ee330000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111',jsonb_build_object('inputHash',repeat('c',64),'reason','Cancel only unused request'))->>'decisionDomain'='knowledge_files','committed original recovered instead of cancelled');
select pg_temp.check_it(public.cancel_unused_knowledge_decision('ee330000-0000-4000-8000-000000000099','ee330000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111',jsonb_build_object('inputHash',repeat('c',64),'reason','Cancel only unused request'))->>'state'='cancelled','unused file request cancellation saved');
select pg_temp.check_it(pg_temp.original('ee330000-0000-4000-8000-000000000099')->>'state'='decision_cancelled','late cancelled upload cannot save');
select pg_temp.original('ee330000-0000-4000-8000-000000000011');
select pg_temp.check_it(pg_temp.decide(gen_random_uuid(),pg_temp.command('ee330000-0000-4000-8000-000000000011','stop_upload'))->>'state'='saved','unfinished upload stopped');
select pg_temp.check_it(pg_temp.finish_file('ee330000-0000-4000-8000-000000000011')->>'state'='stopped','late uploaded bytes cannot revive stopped request');
select pg_temp.original('ee330000-0000-4000-8000-000000000012');select pg_temp.finish_file('ee330000-0000-4000-8000-000000000012');
select pg_temp.decide('ee330000-0000-4000-8000-000000000022',pg_temp.command('ee330000-0000-4000-8000-000000000012','extract'));
insert into st values('claim3',public.claim_knowledge_file_extraction('ee330000-0000-4000-8000-000000000022'));
select pg_temp.check_it(pg_temp.decide(gen_random_uuid(),pg_temp.command('ee330000-0000-4000-8000-000000000012','stop_extraction',jsonb_build_object('extractionId','ee330000-0000-4000-8000-000000000022','expectedExtractionRevision',2)))->>'state'='saved','running extraction stop saved');
select pg_temp.check_it(public.record_knowledge_file_extraction('ee330000-0000-4000-8000-000000000022',(select(v->>'claimToken')::uuid from st where k='claim3'),(select v from st where k='receipt'))->>'state'='stopped','late complete receipt cannot revive stopped extraction');
select pg_temp.check_it((select receipt is not null from public.knowledge_file_extractions where id='ee330000-0000-4000-8000-000000000022'),'late extraction receipt retained');
select set_config('p11.knowledge_file_scope','',true);
do $$begin begin update public.knowledge_files set state='pending'where id='ee330000-0000-4000-8000-000000000010';raise exception 'guard missing'using errcode='P0002';exception when sqlstate'P0001'then perform pg_temp.check_it(true,'unrecorded file change denied');end;begin update public.knowledge_file_decisions set kind='changed'where id='ee330000-0000-4000-8000-000000000010';raise exception 'guard missing'using errcode='P0002';exception when sqlstate'P0001'then perform pg_temp.check_it(true,'decision history immutable');end;end$$;
select pg_temp.check_it(not has_table_privilege('authenticated','public.knowledge_files','select')and not has_table_privilege('anon','public.knowledge_file_extractions','select'),'file evidence private to trusted server');
select pg_temp.check_it(not has_function_privilege('authenticated','public.begin_knowledge_file(uuid,uuid,uuid,jsonb)','execute')and not has_function_privilege('anon','public.read_knowledge_files(uuid,uuid,jsonb)','execute'),'privileged native entry points closed');
select pg_temp.check_it((select not public from storage.buckets where id='knowledge-originals'),'original storage bucket private');
select pg_temp.check_it(exists(select 1 from pg_policies where schemaname='storage'and tablename='objects'and policyname='knowledge_originals_private'and permissive='RESTRICTIVE'),'private bucket cannot inherit broad permissive policy');
select pg_temp.check_it(not exists(select 1 from public.shared_action_events where property_id='ee330000-0000-4000-8000-000000000001'and training_eligible),'actions not training eligible');
select pg_temp.check_it(not exists(select 1 from public.shared_action_events where property_id='ee330000-0000-4000-8000-000000000001'and(request::text||result::text)like'%Deliberate reviewed correction%'),'shared activity excludes source text');
select pg_temp.check_it((select count(*)from public.shared_action_events where property_id='ee330000-0000-4000-8000-000000000001'and action='knowledge.file.extraction_received'and actor_id is null and service_principal='knowledge.files')=3,'machine receipts have distinct service attribution');

do $$declare prior_role text;begin
 select role into prior_role from public.profiles where id='11111111-1111-1111-1111-111111111111';
 update public.profiles set role=null where id='11111111-1111-1111-1111-111111111111';
 perform pg_temp.check_it(pg_temp.original(gen_random_uuid())->>'state'='forbidden','current management access required for upload');
 perform pg_temp.check_it(pg_temp.decide(gen_random_uuid(),pg_temp.command('ee330000-0000-4000-8000-000000000010','download'))->>'state'='forbidden','download preparation rechecks current management access');
 update public.profiles set role=prior_role where id='11111111-1111-1111-1111-111111111111';
end$$;
select pg_temp.check_it(pg_temp.decide(gen_random_uuid(),pg_temp.command('ee330000-0000-4000-8000-000000000010','download')||'{"expectedRevision":1}')->>'state'='file_changed','old file version cannot prepare a current download');
insert into public.knowledge_file_extractions(id,file_id,property_id,org_id,actor_id,input,state)
select md5('private-extraction-history-'||n)::uuid,'ee330000-0000-4000-8000-000000000010','ee330000-0000-4000-8000-000000000001','22222222-2222-2222-2222-222222222222','11111111-1111-1111-1111-111111111111','{}','held'from generate_series(1,1001)n;
insert into st values('extractionTail',public.read_knowledge_files('ee330000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111','{"kind":"extractions","fileId":"ee330000-0000-4000-8000-000000000010","offset":1000}'));
select pg_temp.check_it(v->>'total'='1003'and jsonb_array_length(v->'items')=3 and v->'nextOffset'='null','all retained extractions reachable beyond REST cap')from st where k='extractionTail';
insert into public.knowledge_file_decisions(id,property_id,org_id,actor_id,file_id,kind,input,input_hash,result)
select md5('private-file-decision-history-'||n)::uuid,'ee330000-0000-4000-8000-000000000001','22222222-2222-2222-2222-222222222222','11111111-1111-1111-1111-111111111111','ee330000-0000-4000-8000-000000000010','fixture','{}','fixture','{}'from generate_series(1,1001)n;
insert into st values('decisionTail',public.read_knowledge_files('ee330000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111','{"kind":"decisions","fileId":"ee330000-0000-4000-8000-000000000010","offset":1000}'));
select pg_temp.check_it((v->>'total')::int>1001 and jsonb_array_length(v->'items')=(v->>'total')::int-1000 and v->'nextOffset'='null','all original decisions reachable beyond REST cap')from st where k='decisionTail';
insert into st values('filePage',public.read_knowledge_files('ee330000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111','{}'));
insert into public.knowledge_files(id,property_id,org_id,actor_id,input,input_hash,storage_path)select md5('private-file-history-'||n)::uuid,'ee330000-0000-4000-8000-000000000001','22222222-2222-2222-2222-222222222222','11111111-1111-1111-1111-111111111111','{}','fixture','fixture/'||n from generate_series(1,1001)n;
select pg_temp.check_it(public.read_knowledge_files('ee330000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111',jsonb_build_object('offset',20,'expectedHash',(select v->>'historyHash'from st where k='filePage')))->>'state'='history_changed','changed inventory page fence');
insert into st values('tail',public.read_knowledge_files('ee330000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111','{"offset":1000}'));
select pg_temp.check_it(v->>'total'='1004'and jsonb_array_length(v->'items')=4 and v->'nextOffset'='null','all file records reachable beyond REST cap')from st where k='tail';
select pg_temp.check_it(not exists(select 1 from public.shared_jobs where property_id='ee330000-0000-4000-8000-000000000001'),'original extraction does not invoke model jobs');
select n as passed_assertions from assertion_count;
ROLLBACK;
